package bitbucket

import (
	"context"
	"fmt"
	"net/http"
)

// FetchDiff retrieves the unified diff for a pull request.
// The caller's context bounds the whole operation, including the body read.
func (c *Client) FetchDiff(ctx context.Context, project, repo string, pr int) (string, error) {
	u := fmt.Sprintf("%s/projects/%s/repos/%s/pull-requests/%d/diff", c.base, project, repo, pr)
	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, u, nil)
	if err != nil {
		return "", fmt.Errorf("build diff request: %w", err)
	}
	req.Header.Set("Authorization", "Bearer "+c.token)
	return c.getTextCapped(context.Background(), req, maxDiffBytes)
}
